import {ReceivingWorkflow} from './receiving.ts';
const api=async(path:string,body?:unknown)=>{const csrf=document.cookie.split('; ').find(c=>c.startsWith('csrf_token='))?.split('=').slice(1).join('=');const r=await fetch(path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':decodeURIComponent(csrf||'')},body:body===undefined?undefined:JSON.stringify(body)});const v=await r.json();if(!r.ok)throw Object.assign(Error(v.detail||'Receiving unavailable'),{status:r.status});return v;};
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const workflow=new ReceivingWorkflow(api),root=document.querySelector('#receiving-list')!;let after=0;
async function list(){try{const p=await api('/api/receiving/orders?after='+after);root.innerHTML=p.rows.map((r:any)=>`<p>PO #${Number(r.id)} · ${esc(r.supplier)} · ${r.origin==='V4'?`<button data-receive="${Number(r.id)}">Receive</button>`:'Legacy receiving · '+esc(r.status)}</p>`).join('')+(p.next_cursor?'<button id="receiving-more">Next orders</button>':'');root.querySelectorAll<HTMLButtonElement>('[data-receive]').forEach(b=>b.onclick=()=>void workflow.open(Number(b.dataset.receive)).catch(e=>alert(e.message)));root.querySelector<HTMLButtonElement>('#receiving-more')?.addEventListener('click',()=>{after=p.next_cursor;void list();});}catch(e){root.textContent=(e as Error).message;}}
void list();
